begin;

alter table public.subscription_plans
  add column if not exists setup_fee_pence integer not null default 0 check (setup_fee_pence >= 0),
  add column if not exists is_public boolean not null default true,
  add column if not exists supports_monthly boolean not null default true,
  add column if not exists supports_annual boolean not null default true,
  add column if not exists custom_pricing boolean not null default false,
  add column if not exists currency text not null default 'gbp' check (currency ~ '^[a-z]{3}$'),
  add column if not exists metadata jsonb not null default '{}'::jsonb;

update public.subscription_plans
set code='professional',name='Professional',updated_at=now()
where code='pro' and not exists(select 1 from public.subscription_plans where code='professional');

insert into public.subscription_plans(code,name,description,monthly_price_pence,annual_price_pence,trial_days,setup_fee_pence,is_public,supports_monthly,supports_annual,custom_pricing,features,sort_order)
values
('free','Free','Start taking orders with essential platform tools.',0,0,0,0,true,true,true,false,'{"max_menus":1,"max_locations":1,"loyalty":false,"stamp_cards":false,"referrals":false,"birthday_rewards":false,"vip":false,"challenges":false,"crm":false,"marketing_automation":false,"ai_insights":false,"advanced_analytics":false,"api_access":false,"max_team_members":1,"max_kitchen_displays":1,"max_printers":1,"white_label":false,"custom_branding":false,"sso_ready":false,"support_level":"standard","priority_processing":false,"max_campaigns":0,"max_automations":0,"max_api_requests_month":0,"storage_mb":250,"locations":1,"staff_users":1,"advanced_reporting":false,"marketing":false}'::jsonb,0),
('starter','Starter','Essential online ordering for independent restaurants.',2900,29000,14,0,true,true,true,false,'{"max_menus":1,"max_locations":1,"loyalty":true,"stamp_cards":true,"referrals":true,"birthday_rewards":true,"vip":false,"challenges":false,"crm":true,"marketing_automation":false,"ai_insights":false,"advanced_analytics":false,"api_access":false,"max_team_members":3,"max_kitchen_displays":2,"max_printers":2,"white_label":false,"custom_branding":false,"sso_ready":false,"support_level":"standard","priority_processing":false,"max_campaigns":3,"max_automations":0,"max_api_requests_month":0,"storage_mb":1000,"locations":1,"staff_users":3,"advanced_reporting":false,"marketing":true}'::jsonb,10),
('professional','Professional','Advanced operations, loyalty, CRM and marketing automation.',5900,59000,14,0,true,true,true,false,'{"max_menus":3,"max_locations":3,"loyalty":true,"stamp_cards":true,"referrals":true,"birthday_rewards":true,"vip":true,"challenges":true,"crm":true,"marketing_automation":true,"ai_insights":true,"advanced_analytics":true,"api_access":false,"max_team_members":10,"max_kitchen_displays":5,"max_printers":5,"white_label":false,"custom_branding":true,"sso_ready":false,"support_level":"priority","priority_processing":true,"max_campaigns":25,"max_automations":10,"max_api_requests_month":0,"storage_mb":5000,"locations":3,"staff_users":10,"advanced_reporting":true,"marketing":true,"ai_menu_import":true,"multi_location":true,"priority_support":true}'::jsonb,20),
('growth','Growth','High-volume growth tooling with API access and expanded limits.',9900,99000,14,0,true,true,true,false,'{"max_menus":10,"max_locations":10,"loyalty":true,"stamp_cards":true,"referrals":true,"birthday_rewards":true,"vip":true,"challenges":true,"crm":true,"marketing_automation":true,"ai_insights":true,"advanced_analytics":true,"api_access":true,"max_team_members":50,"max_kitchen_displays":20,"max_printers":20,"white_label":true,"custom_branding":true,"sso_ready":false,"support_level":"priority","priority_processing":true,"max_campaigns":-1,"max_automations":50,"max_api_requests_month":100000,"storage_mb":25000,"locations":10,"staff_users":50,"advanced_reporting":true,"marketing":true,"ai_menu_import":true,"multi_location":true,"priority_support":true}'::jsonb,30),
