on conflict(code) do update set name=excluded.name,description=excluded.description,trial_days=excluded.trial_days,setup_fee_pence=excluded.setup_fee_pence,is_public=excluded.is_public,supports_monthly=excluded.supports_monthly,supports_annual=excluded.supports_annual,custom_pricing=excluded.custom_pricing,features=excluded.features,sort_order=excluded.sort_order,updated_at=now();

alter table public.restaurant_subscriptions
 add column if not exists stripe_price_id text,
 add column if not exists paused_at timestamptz,
 add column if not exists resume_at timestamptz,
 add column if not exists ended_at timestamptz,
 add column if not exists comped_until timestamptz,
 add column if not exists custom_price_pence integer check(custom_price_pence is null or custom_price_pence>=0),
 add column if not exists trial_extension_days integer not null default 0 check(trial_extension_days>=0),
 add column if not exists cancellation_reason text,
 add column if not exists metadata jsonb not null default '{}'::jsonb;

create table if not exists public.restaurant_subscription_invoices(
 id uuid primary key default gen_random_uuid(),restaurant_id uuid not null references public.restaurants(id) on delete cascade,subscription_id uuid references public.restaurant_subscriptions(id) on delete set null,stripe_invoice_id text not null unique,invoice_number text,status text not null default 'draft',currency text not null default 'gbp',subtotal_pence integer not null default 0,discount_pence integer not null default 0,tax_pence integer not null default 0,total_pence integer not null default 0,amount_paid_pence integer not null default 0,amount_due_pence integer not null default 0,hosted_invoice_url text,invoice_pdf_url text,period_start timestamptz,period_end timestamptz,due_at timestamptz,paid_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create index if not exists restaurant_subscription_invoices_restaurant_idx on public.restaurant_subscription_invoices(restaurant_id,created_at desc);

create table if not exists public.restaurant_billing_credits(id uuid primary key default gen_random_uuid(),restaurant_id uuid not null references public.restaurants(id) on delete cascade,subscription_id uuid references public.restaurant_subscriptions(id) on delete set null,amount_pence integer not null check(amount_pence>0),currency text not null default 'gbp',reason text not null,stripe_customer_balance_transaction_id text unique,issued_by uuid references auth.users(id) on delete set null,status text not null default 'pending' check(status in('pending','applied','failed','void')),metadata jsonb not null default '{}'::jsonb,created_at timestamptz not null default now(),applied_at timestamptz);
create table if not exists public.restaurant_subscription_cancellations(id uuid primary key default gen_random_uuid(),restaurant_id uuid not null references public.restaurants(id) on delete cascade,subscription_id uuid references public.restaurant_subscriptions(id) on delete set null,reason_code text not null default 'other',reason_text text,requested_by uuid references auth.users(id) on delete set null,requested_at timestamptz not null default now(),effective_at timestamptz,reversed_at timestamptz,metadata jsonb not null default '{}'::jsonb);
create index if not exists restaurant_subscription_cancellations_restaurant_idx on public.restaurant_subscription_cancellations(restaurant_id,requested_at desc);
create table if not exists public.restaurant_subscription_trial_history(id uuid primary key default gen_random_uuid(),restaurant_id uuid not null references public.restaurants(id) on delete cascade,user_id uuid references auth.users(id) on delete set null,plan_id uuid references public.subscription_plans(id) on delete set null,started_at timestamptz not null default now(),ended_at timestamptz,source text not null default 'stripe',metadata jsonb not null default '{}'::jsonb);
create unique index if not exists restaurant_trial_once_per_restaurant_idx on public.restaurant_subscription_trial_history(restaurant_id) where source='stripe';
create index if not exists restaurant_trial_user_idx on public.restaurant_subscription_trial_history(user_id,started_at desc);
create table if not exists public.restaurant_subscription_usage(restaurant_id uuid not null references public.restaurants(id) on delete cascade,metric_key text not null check(metric_key~'^[a-z0-9_]+$'),period_start date not null,period_end date not null,quantity bigint not null default 0 check(quantity>=0),bytes_used bigint not null default 0 check(bytes_used>=0),metadata jsonb not null default '{}'::jsonb,updated_at timestamptz not null default now(),primary key(restaurant_id,metric_key,period_start));
create table if not exists public.restaurant_kitchen_displays(id uuid primary key default gen_random_uuid(),restaurant_id uuid not null references public.restaurants(id) on delete cascade,name text not null,device_key text not null unique default encode(gen_random_bytes(18),'hex'),is_active boolean not null default true,last_seen_at timestamptz,metadata jsonb not null default '{}'::jsonb,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create index if not exists restaurant_kitchen_displays_restaurant_idx on public.restaurant_kitchen_displays(restaurant_id,is_active);
create table if not exists public.restaurant_team_roles(id uuid primary key default gen_random_uuid(),restaurant_id uuid not null references public.restaurants(id) on delete cascade,key text not null check(key~'^[a-z0-9_-]+$'),name text not null,permissions jsonb not null default '[]'::jsonb check(jsonb_typeof(permissions)='array'),is_system boolean not null default false,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(restaurant_id,key));
alter table public.restaurant_members add column if not exists status text not null default 'active' check(status in('active','suspended')),add column if not exists custom_role_id uuid references public.restaurant_team_roles(id) on delete set null,add column if not exists permissions jsonb not null default '[]'::jsonb check(jsonb_typeof(permissions)='array'),add column if not exists invited_by uuid references auth.users(id) on delete set null,add column if not exists suspended_at timestamptz,add column if not exists last_active_at timestamptz;
create table if not exists public.restaurant_team_invites(id uuid primary key default gen_random_uuid(),restaurant_id uuid not null references public.restaurants(id) on delete cascade,email text not null,role public.restaurant_member_role not null default 'staff',custom_role_id uuid references public.restaurant_team_roles(id) on delete set null,permissions jsonb not null default '[]'::jsonb check(jsonb_typeof(permissions)='array'),token_hash text not null unique,invited_by uuid not null references auth.users(id) on delete cascade,expires_at timestamptz not null,accepted_at timestamptz,revoked_at timestamptz,created_at timestamptz not null default now());
create unique index if not exists restaurant_team_pending_invite_email_idx on public.restaurant_team_invites(restaurant_id,lower(email)) where accepted_at is null and revoked_at is null;
create table if not exists public.restaurant_team_activity(id bigint generated always as identity primary key,restaurant_id uuid not null references public.restaurants(id) on delete cascade,actor_user_id uuid references auth.users(id) on delete set null,target_user_id uuid references auth.users(id) on delete set null,action text not null,details jsonb not null default '{}'::jsonb,created_at timestamptz not null default now());
create index if not exists restaurant_team_activity_restaurant_idx on public.restaurant_team_activity(restaurant_id,created_at desc);
create table if not exists public.restaurant_enterprise_settings(restaurant_id uuid primary key references public.restaurants(id) on delete cascade,custom_brand_name text,custom_logo_url text,custom_primary_colour text,white_label_domain text unique,sso_enabled boolean not null default false,sso_provider text,sso_metadata jsonb not null default '{}'::jsonb,support_level text not null default 'standard',priority_processing boolean not null default false,dedicated_support_notes text,updated_at timestamptz not null default now());

alter table public.restaurant_subscription_invoices enable row level security;alter table public.restaurant_billing_credits enable row level security;alter table public.restaurant_subscription_cancellations enable row level security;alter table public.restaurant_subscription_trial_history enable row level security;alter table public.restaurant_subscription_usage enable row level security;alter table public.restaurant_kitchen_displays enable row level security;alter table public.restaurant_team_roles enable row level security;alter table public.restaurant_team_invites enable row level security;alter table public.restaurant_team_activity enable row level security;alter table public.restaurant_enterprise_settings enable row level security;
revoke all on public.restaurant_subscription_invoices,public.restaurant_billing_credits,public.restaurant_subscription_cancellations,public.restaurant_subscription_trial_history,public.restaurant_subscription_usage,public.restaurant_kitchen_displays,public.restaurant_team_roles,public.restaurant_team_invites,public.restaurant_team_activity,public.restaurant_enterprise_settings from public,anon,authenticated;
grant select on public.restaurant_subscription_invoices,public.restaurant_billing_credits,public.restaurant_subscription_cancellations,public.restaurant_subscription_usage,public.restaurant_kitchen_displays,public.restaurant_team_roles,public.restaurant_team_invites,public.restaurant_team_activity,public.restaurant_enterprise_settings to authenticated;

create or replace function private.restaurant_member_of(p_restaurant_id uuid) returns boolean language sql stable security definer set search_path='' as $$select exists(select 1 from public.restaurant_members rm where rm.restaurant_id=p_restaurant_id and rm.user_id=(select auth.uid()) and rm.status='active')$$;
create or replace function private.restaurant_owner_of(p_restaurant_id uuid) returns boolean language sql stable security definer set search_path='' as $$select exists(select 1 from public.restaurant_members rm where rm.restaurant_id=p_restaurant_id and rm.user_id=(select auth.uid()) and rm.role='owner' and rm.status='active')$$;
create or replace function private.platform_admin_has_permission(p_permission text) returns boolean language sql stable security definer set search_path='' as $$select coalesce(p_permission=any(private.platform_admin_permissions(private.current_platform_admin_role())),false)$$;

create policy subscription_invoices_member_read on public.restaurant_subscription_invoices for select to authenticated using(private.restaurant_member_of(restaurant_id) or private.platform_admin_has_permission('finance:view'));
create policy billing_credits_member_read on public.restaurant_billing_credits for select to authenticated using(private.restaurant_member_of(restaurant_id) or private.platform_admin_has_permission('finance:view'));
create policy subscription_cancellations_member_read on public.restaurant_subscription_cancellations for select to authenticated using(private.restaurant_member_of(restaurant_id) or private.platform_admin_has_permission('finance:view'));
create policy subscription_usage_member_read on public.restaurant_subscription_usage for select to authenticated using(private.restaurant_member_of(restaurant_id) or private.platform_admin_has_permission('finance:view'));
create policy kitchen_displays_member_read on public.restaurant_kitchen_displays for select to authenticated using(private.restaurant_member_of(restaurant_id) or private.platform_admin_has_permission('restaurants:view'));
create policy team_roles_member_read on public.restaurant_team_roles for select to authenticated using(private.restaurant_member_of(restaurant_id) or private.platform_admin_has_permission('restaurants:view'));
create policy team_invites_owner_read on public.restaurant_team_invites for select to authenticated using(private.restaurant_owner_of(restaurant_id) or private.platform_admin_has_permission('restaurants:view'));
create policy team_activity_owner_read on public.restaurant_team_activity for select to authenticated using(private.restaurant_owner_of(restaurant_id) or private.platform_admin_has_permission('restaurants:view'));
create policy enterprise_settings_member_read on public.restaurant_enterprise_settings for select to authenticated using(private.restaurant_member_of(restaurant_id) or private.platform_admin_has_permission('restaurants:view'));

drop policy if exists subscription_plans_read on public.subscription_plans;
create policy subscription_plans_read on public.subscription_plans for select to authenticated using(is_active and(is_public or exists(select 1 from public.restaurant_subscriptions s join public.restaurant_members rm on rm.restaurant_id=s.restaurant_id where s.plan_id=subscription_plans.id and rm.user_id=(select auth.uid())) or private.platform_admin_has_permission('finance:view')));

create or replace function private.restaurant_plan_feature(p_restaurant_id uuid,p_feature text) returns jsonb language sql stable security definer set search_path='' as $$select coalesce(s.metadata->'feature_overrides'->p_feature,p.features->p_feature,'null'::jsonb) from public.restaurant_subscriptions s join public.subscription_plans p on p.id=s.plan_id where s.restaurant_id=p_restaurant_id and(s.status in('trialing','active') or(s.status='past_due' and s.grace_period_ends_at>now()) or s.comped_until>now()) limit 1$$;

create or replace function public.restaurant_has_subscription_feature(p_feature text) returns boolean language plpgsql stable security definer set search_path='' as $$declare rid uuid;feature jsonb;begin select restaurant_id into rid from public.restaurant_members where user_id=(select auth.uid()) and status='active' order by created_at limit 1;if rid is null then return false;end if;feature:=private.restaurant_plan_feature(rid,p_feature);return case when jsonb_typeof(feature)='boolean' then(feature#>>'{}')::boolean else feature is not null and feature<>'null'::jsonb end;end$$;

create or replace function private.restaurant_usage_value(p_restaurant_id uuid,p_metric text) returns bigint language plpgsql stable security definer set search_path='' as $$declare result bigint:=0;begin case p_metric when 'max_menus' then select case when exists(select 1 from public.menu_categories where restaurant_id=p_restaurant_id) then 1 else 0 end into result;when 'max_locations' then select count(*) into result from public.restaurant_locations where restaurant_id=p_restaurant_id and is_active;when 'max_team_members' then select count(*) into result from public.restaurant_members where restaurant_id=p_restaurant_id and status='active';when 'max_kitchen_displays' then select count(*) into result from public.restaurant_kitchen_displays where restaurant_id=p_restaurant_id and is_active;when 'max_printers' then select count(*) into result from public.restaurant_printers where restaurant_id=p_restaurant_id and is_active;when 'max_campaigns' then select count(*) into result from public.restaurant_marketing_campaigns where restaurant_id=p_restaurant_id and status<>'archived';when 'max_automations' then select count(*) into result from public.restaurant_marketing_automations where restaurant_id=p_restaurant_id and status<>'archived';when 'max_api_requests_month' then select coalesce(sum(quantity),0) into result from public.restaurant_subscription_usage where restaurant_id=p_restaurant_id and metric_key='api_requests' and period_start=date_trunc('month',current_date)::date;when 'storage_mb' then select coalesce(ceil(sum(bytes_used)::numeric/1048576),0)::bigint into result from public.restaurant_subscription_usage where restaurant_id=p_restaurant_id and metric_key='storage' and period_start=date_trunc('month',current_date)::date;else result:=0;end case;return coalesce(result,0);end$$;

create or replace function public.get_restaurant_subscription_usage() returns jsonb language plpgsql stable security definer set search_path='' as $$declare rid uuid;features jsonb;usage jsonb:='{}'::jsonb;k text;v jsonb;current_value bigint;begin select rm.restaurant_id,p.features||coalesce(s.metadata->'feature_overrides','{}'::jsonb) into rid,features from public.restaurant_members rm join public.restaurant_subscriptions s on s.restaurant_id=rm.restaurant_id join public.subscription_plans p on p.id=s.plan_id where rm.user_id=(select auth.uid()) and rm.status='active' order by rm.created_at limit 1;if rid is null then raise exception 'Restaurant subscription not found' using errcode='42501';end if;for k,v in select key,value from jsonb_each(features) loop if k like 'max_%' or k='storage_mb' then current_value:=private.restaurant_usage_value(rid,k);usage:=usage||jsonb_build_object(k,jsonb_build_object('used',current_value,'limit',case when jsonb_typeof(v)='number' then(v#>>'{}')::bigint else 0 end,'unlimited',case when jsonb_typeof(v)='number' then(v#>>'{}')::bigint=-1 else false end));end if;end loop;return usage;end$$;
create or replace function public.assert_restaurant_plan_limit(p_feature text,p_increment integer default 1) returns jsonb language plpgsql security definer set search_path='' as $$declare rid uuid;feature jsonb;lim bigint;used bigint;begin if p_increment<0 then raise exception 'Invalid increment';end if;select restaurant_id into rid from public.restaurant_members where user_id=(select auth.uid()) and status='active' order by created_at limit 1;if rid is null then raise exception 'Restaurant membership not found' using errcode='42501';end if;feature:=private.restaurant_plan_feature(rid,p_feature);if feature is null or feature='null'::jsonb or jsonb_typeof(feature)<>'number' then raise exception 'Plan limit is not configured for %',p_feature using errcode='42501';end if;lim:=(feature#>>'{}')::bigint;used:=private.restaurant_usage_value(rid,p_feature);if lim<>-1 and used+p_increment>lim then raise exception 'Plan limit reached for % (% of % used)',p_feature,used,lim using errcode='42501';end if;return jsonb_build_object('allowed',true,'feature',p_feature,'used',used,'limit',lim,'remaining',case when lim=-1 then null else greatest(lim-used,0) end);end$$;
create or replace function public.record_restaurant_subscription_usage(p_metric_key text,p_quantity bigint default 1,p_bytes bigint default 0) returns void language plpgsql security definer set search_path='' as $$declare rid uuid;start_date date:=date_trunc('month',current_date)::date;end_date date:=(date_trunc('month',current_date)+interval '1 month-1 day')::date;begin if p_quantity<0 or p_bytes<0 then raise exception 'Usage increments must be non-negative';end if;select restaurant_id into rid from public.restaurant_members where user_id=(select auth.uid()) and status='active' order by created_at limit 1;if rid is null then raise exception 'Restaurant membership not found' using errcode='42501';end if;insert into public.restaurant_subscription_usage(restaurant_id,metric_key,period_start,period_end,quantity,bytes_used) values(rid,p_metric_key,start_date,end_date,p_quantity,p_bytes) on conflict(restaurant_id,metric_key,period_start) do update set quantity=restaurant_subscription_usage.quantity+excluded.quantity,bytes_used=restaurant_subscription_usage.bytes_used+excluded.bytes_used,updated_at=now();end$$;

create or replace function public.get_restaurant_billing_dashboard() returns jsonb language plpgsql stable security definer set search_path='' as $$declare rid uuid;result jsonb;begin select restaurant_id into rid from public.restaurant_members where user_id=(select auth.uid()) and status='active' order by created_at limit 1;if rid is null then raise exception 'Restaurant membership not found' using errcode='42501';end if;select jsonb_build_object('restaurant_id',rid,'subscription',case when s.id is null then null else jsonb_build_object('id',s.id,'status',s.status,'billing_interval',s.billing_interval,'trial_ends_at',s.trial_ends_at,'current_period_start',s.current_period_start,'current_period_end',s.current_period_end,'cancel_at_period_end',s.cancel_at_period_end,'grace_period_ends_at',s.grace_period_ends_at,'paused_at',s.paused_at,'resume_at',s.resume_at,'comped_until',s.comped_until,'custom_price_pence',s.custom_price_pence,'plan',to_jsonb(p)-'stripe_monthly_price_id'-'stripe_annual_price_id') end,'plans',coalesce((select jsonb_agg(to_jsonb(sp)-'stripe_monthly_price_id'-'stripe_annual_price_id' order by sp.sort_order) from public.subscription_plans sp where sp.is_active and(sp.is_public or sp.id=s.plan_id)),'[]'::jsonb),'usage',public.get_restaurant_subscription_usage(),'invoices',coalesce((select jsonb_agg(to_jsonb(i) order by i.created_at desc) from(select * from public.restaurant_subscription_invoices where restaurant_id=rid order by created_at desc limit 24)i),'[]'::jsonb),'credits',coalesce((select jsonb_agg(to_jsonb(c) order by c.created_at desc) from(select * from public.restaurant_billing_credits where restaurant_id=rid order by created_at desc limit 24)c),'[]'::jsonb),'enterprise',coalesce((select to_jsonb(e) from public.restaurant_enterprise_settings e where e.restaurant_id=rid),'{}'::jsonb)) into result from(select rid)x left join public.restaurant_subscriptions s on s.restaurant_id=rid left join public.subscription_plans p on p.id=s.plan_id;return result;end$$;

create or replace function public.get_restaurant_team() returns jsonb language plpgsql stable security definer set search_path='' as $$declare rid uuid;begin select restaurant_id into rid from public.restaurant_members where user_id=(select auth.uid()) and status='active' order by created_at limit 1;if rid is null or not private.restaurant_owner_of(rid) then raise exception 'Restaurant owner access required' using errcode='42501';end if;return jsonb_build_object('members',coalesce((select jsonb_agg(jsonb_build_object('id',rm.id,'user_id',rm.user_id,'email',u.email,'role',rm.role,'status',rm.status,'permissions',rm.permissions,'custom_role_id',rm.custom_role_id,'last_active_at',rm.last_active_at,'created_at',rm.created_at) order by rm.created_at) from public.restaurant_members rm join auth.users u on u.id=rm.user_id where rm.restaurant_id=rid),'[]'::jsonb),'invites',coalesce((select jsonb_agg(to_jsonb(i)-'token_hash' order by i.created_at desc) from public.restaurant_team_invites i where i.restaurant_id=rid and i.accepted_at is null and i.revoked_at is null),'[]'::jsonb),'roles',coalesce((select jsonb_agg(to_jsonb(r) order by r.name) from public.restaurant_team_roles r where r.restaurant_id=rid),'[]'::jsonb),'activity',coalesce((select jsonb_agg(to_jsonb(a) order by a.created_at desc) from(select * from public.restaurant_team_activity where restaurant_id=rid order by created_at desc limit 100)a),'[]'::jsonb));end$$;
create or replace function public.manage_restaurant_team_member(p_user_id uuid,p_action text,p_role public.restaurant_member_role default null,p_permissions jsonb default null) returns void language plpgsql security definer set search_path='' as $$declare rid uuid;target public.restaurant_members%rowtype;begin select restaurant_id into rid from public.restaurant_members where user_id=(select auth.uid()) and role='owner' and status='active' order by created_at limit 1;if rid is null then raise exception 'Restaurant owner access required' using errcode='42501';end if;select * into target from public.restaurant_members where restaurant_id=rid and user_id=p_user_id;if target.id is null then raise exception 'Team member not found';end if;if target.role='owner' and p_user_id<>(select auth.uid()) then raise exception 'Owner membership cannot be changed here' using errcode='42501';end if;if p_action='suspend' then update public.restaurant_members set status='suspended',suspended_at=now(),updated_at=now() where id=target.id;elsif p_action='resume' then update public.restaurant_members set status='active',suspended_at=null,updated_at=now() where id=target.id;elsif p_action='remove' then if p_user_id=(select auth.uid()) then raise exception 'Owner cannot remove their own membership';end if;delete from public.restaurant_members where id=target.id;elsif p_action='update' then update public.restaurant_members set role=coalesce(p_role,role),permissions=coalesce(p_permissions,permissions),updated_at=now() where id=target.id;else raise exception 'Unsupported team action';end if;insert into public.restaurant_team_activity(restaurant_id,actor_user_id,target_user_id,action,details) values(rid,(select auth.uid()),p_user_id,p_action,jsonb_build_object('role',p_role,'permissions',p_permissions));end$$;
create or replace function public.accept_restaurant_team_invite(p_token text) returns uuid language plpgsql security definer set search_path='' as $$declare token_digest text:=encode(digest(p_token,'sha256'),'hex');invite public.restaurant_team_invites%rowtype;user_email text;begin if auth.uid() is null then raise exception 'Authentication required' using errcode='42501';end if;select email into user_email from auth.users where id=(select auth.uid());select * into invite from public.restaurant_team_invites where token_hash=token_digest and accepted_at is null and revoked_at is null and expires_at>now() for update;if invite.id is null then raise exception 'Invite is invalid or expired';end if;if lower(invite.email)<>lower(user_email) then raise exception 'Invite email does not match signed-in account' using errcode='42501';end if;if private.restaurant_usage_value(invite.restaurant_id,'max_team_members')>=coalesce((private.restaurant_plan_feature(invite.restaurant_id,'max_team_members')#>>'{}')::bigint,0) and coalesce((private.restaurant_plan_feature(invite.restaurant_id,'max_team_members')#>>'{}')::bigint,0)<>-1 then raise exception 'Team member plan limit reached' using errcode='42501';end if;insert into public.restaurant_members(restaurant_id,user_id,role,custom_role_id,permissions,invited_by,status) values(invite.restaurant_id,(select auth.uid()),invite.role,invite.custom_role_id,invite.permissions,invite.invited_by,'active') on conflict(restaurant_id,user_id) do update set role=excluded.role,custom_role_id=excluded.custom_role_id,permissions=excluded.permissions,status='active',updated_at=now();update public.restaurant_team_invites set accepted_at=now() where id=invite.id;insert into public.restaurant_team_activity(restaurant_id,actor_user_id,target_user_id,action,details) values(invite.restaurant_id,(select auth.uid()),(select auth.uid()),'invite_accepted',jsonb_build_object('invite_id',invite.id));return invite.restaurant_id;end$$;

create or replace function private.notify_restaurant_members(p_restaurant_id uuid,p_type text,p_title text,p_body text,p_dedupe text,p_metadata jsonb default '{}'::jsonb) returns void language plpgsql security definer set search_path='' as $$begin insert into public.customer_notifications(customer_user_id,restaurant_id,notification_type,title,body,action_url,metadata,dedupe_key) select rm.user_id,p_restaurant_id,p_type,p_title,p_body,'/subscription',p_metadata,p_dedupe||':'||rm.user_id::text from public.restaurant_members rm where rm.restaurant_id=p_restaurant_id and rm.status='active' on conflict do nothing;end$$;
create or replace function private.subscription_event_notification_trigger() returns trigger language plpgsql security definer set search_path='' as $$begin if new.event_type in('invoice_payment_failed','subscription_renewed','subscription_upgraded','subscription_downgraded','subscription_cancelled','subscription_resumed','trial_ending','invoice_available') then perform private.notify_restaurant_members(new.restaurant_id,'subscription_'||new.event_type,case new.event_type when 'invoice_payment_failed' then 'Payment failed' when 'subscription_renewed' then 'Subscription renewed' when 'subscription_upgraded' then 'Plan upgraded' when 'subscription_downgraded' then 'Plan changed' when 'subscription_cancelled' then 'Subscription cancelled' when 'subscription_resumed' then 'Subscription restarted' when 'trial_ending' then 'Your trial is ending soon' when 'invoice_available' then 'New invoice available' else 'Subscription update' end,case new.event_type when 'invoice_payment_failed' then 'We could not collect your subscription payment. Update your payment method to keep access.' when 'trial_ending' then 'Your ordered.food trial is nearly over. Review your plan and payment method.' when 'invoice_available' then 'A new subscription invoice is ready to view.' else 'Your ordered.food subscription has been updated.' end,coalesce(new.stripe_event_id,new.id::text),new.details);end if;return new;end$$;
drop trigger if exists restaurant_subscription_event_notifications on public.restaurant_subscription_events;create trigger restaurant_subscription_event_notifications after insert on public.restaurant_subscription_events for each row execute function private.subscription_event_notification_trigger();

create or replace function public.get_platform_subscription_analytics() returns jsonb language plpgsql stable security definer set search_path='' as $$declare result jsonb;begin if not private.platform_admin_has_permission('finance:view') then raise exception 'Finance access required' using errcode='42501';end if;select jsonb_build_object('mrr_pence',coalesce(sum(case when s.status in('active','trialing','past_due') then case when s.custom_price_pence is not null then case when s.billing_interval='annual' then round(s.custom_price_pence/12.0)::bigint else s.custom_price_pence end when s.billing_interval='annual' then round(coalesce(p.annual_price_pence,0)/12.0)::bigint else p.monthly_price_pence end else 0 end),0),'arr_pence',coalesce(sum(case when s.status in('active','trialing','past_due') then case when s.custom_price_pence is not null then case when s.billing_interval='annual' then s.custom_price_pence else s.custom_price_pence*12 end when s.billing_interval='annual' then coalesce(p.annual_price_pence,0) else p.monthly_price_pence*12 end else 0 end),0),'active_subscribers',count(*) filter(where s.status='active'),'trialing',count(*) filter(where s.status='trialing'),'past_due',count(*) filter(where s.status='past_due'),'cancelled_30d',(select count(*) from public.restaurant_subscription_cancellations where requested_at>=now()-interval '30 days'),'trial_conversions_30d',(select count(distinct restaurant_id) from public.restaurant_subscription_events where event_type in('invoice_payment_succeeded','subscription_renewed') and created_at>=now()-interval '30 days' and restaurant_id in(select restaurant_id from public.restaurant_subscription_trial_history)),'subscriber_growth_30d',(select count(*) from public.restaurant_subscriptions where created_at>=now()-interval '30 days'),'plan_distribution',coalesce((select jsonb_agg(jsonb_build_object('code',x.code,'name',x.name,'subscribers',x.subscribers) order by x.subscribers desc) from(select p2.code,p2.name,count(s2.id) subscribers from public.subscription_plans p2 left join public.restaurant_subscriptions s2 on s2.plan_id=p2.id and s2.status in('active','trialing','past_due') group by p2.id,p2.code,p2.name)x),'[]'::jsonb),'cancellation_reasons',coalesce((select jsonb_agg(jsonb_build_object('reason',x.reason_code,'count',x.n) order by x.n desc) from(select reason_code,count(*) n from public.restaurant_subscription_cancellations where requested_at>=now()-interval '90 days' group by reason_code)x),'[]'::jsonb),'revenue_per_restaurant',coalesce((select jsonb_agg(jsonb_build_object('restaurant_id',x.restaurant_id,'restaurant_name',x.name,'revenue_pence',x.revenue) order by x.revenue desc) from(select r.id restaurant_id,r.name,coalesce(sum(i.amount_paid_pence),0) revenue from public.restaurants r left join public.restaurant_subscription_invoices i on i.restaurant_id=r.id and i.paid_at>=now()-interval '12 months' group by r.id,r.name order by revenue desc limit 100)x),'[]'::jsonb)) into result from public.restaurant_subscriptions s left join public.subscription_plans p on p.id=s.plan_id;return result;end$$;
create or replace function public.get_platform_subscription_management() returns jsonb language plpgsql stable security definer set search_path='' as $$begin if not private.platform_admin_has_permission('finance:view') then raise exception 'Finance access required' using errcode='42501';end if;return jsonb_build_object('plans',(select coalesce(jsonb_agg(to_jsonb(p) order by p.sort_order),'[]'::jsonb) from public.subscription_plans p),'subscriptions',(select coalesce(jsonb_agg(jsonb_build_object('id',s.id,'restaurant_id',s.restaurant_id,'restaurant_name',r.name,'status',s.status,'billing_interval',s.billing_interval,'current_period_end',s.current_period_end,'trial_ends_at',s.trial_ends_at,'cancel_at_period_end',s.cancel_at_period_end,'comped_until',s.comped_until,'custom_price_pence',s.custom_price_pence,'plan_id',s.plan_id,'plan_name',p.name,'plan_code',p.code) order by s.updated_at desc),'[]'::jsonb) from public.restaurant_subscriptions s join public.restaurants r on r.id=s.restaurant_id left join public.subscription_plans p on p.id=s.plan_id),'analytics',public.get_platform_subscription_analytics());end$$;
create or replace function public.admin_extend_subscription_trial(p_restaurant_id uuid,p_days integer,p_reason text) returns timestamptz language plpgsql security definer set search_path='' as $$declare new_end timestamptz;begin if not private.platform_admin_has_permission('finance:manage') then raise exception 'Finance management access required' using errcode='42501';end if;if p_days<1 or p_days>90 then raise exception 'Trial extension must be between 1 and 90 days';end if;update public.restaurant_subscriptions set trial_ends_at=greatest(coalesce(trial_ends_at,now()),now())+make_interval(days=>p_days),trial_extension_days=trial_extension_days+p_days,status=case when status in('cancelled','unpaid') then 'trialing' else status end,updated_at=now() where restaurant_id=p_restaurant_id returning trial_ends_at into new_end;if new_end is null then raise exception 'Subscription not found';end if;insert into public.restaurant_subscription_events(restaurant_id,subscription_id,event_type,details) select p_restaurant_id,id,'trial_extended',jsonb_build_object('days',p_days,'reason',p_reason,'admin_user_id',(select auth.uid())) from public.restaurant_subscriptions where restaurant_id=p_restaurant_id;return new_end;end$$;
create or replace function public.admin_comp_restaurant_subscription(p_restaurant_id uuid,p_until timestamptz,p_reason text) returns void language plpgsql security definer set search_path='' as $$begin if not private.platform_admin_has_permission('finance:manage') then raise exception 'Finance management access required' using errcode='42501';end if;if p_until<=now() then raise exception 'Comp end date must be in the future';end if;update public.restaurant_subscriptions set comped_until=p_until,updated_at=now() where restaurant_id=p_restaurant_id;if not found then raise exception 'Subscription not found';end if;insert into public.restaurant_subscription_events(restaurant_id,subscription_id,event_type,details) select p_restaurant_id,id,'subscription_comped',jsonb_build_object('until',p_until,'reason',p_reason,'admin_user_id',(select auth.uid())) from public.restaurant_subscriptions where restaurant_id=p_restaurant_id;end$$;
create or replace function public.admin_create_billing_credit(p_restaurant_id uuid,p_amount_pence integer,p_reason text) returns uuid language plpgsql security definer set search_path='' as $$declare credit_id uuid;begin if not private.platform_admin_has_permission('finance:manage') then raise exception 'Finance management access required' using errcode='42501';end if;if p_amount_pence<=0 then raise exception 'Credit amount must be positive';end if;insert into public.restaurant_billing_credits(restaurant_id,subscription_id,amount_pence,reason,issued_by) select p_restaurant_id,id,p_amount_pence,p_reason,(select auth.uid()) from public.restaurant_subscriptions where restaurant_id=p_restaurant_id returning id into credit_id;if credit_id is null then raise exception 'Subscription not found';end if;return credit_id;end$$;

revoke all on function public.get_restaurant_subscription_usage(),public.assert_restaurant_plan_limit(text,integer),public.record_restaurant_subscription_usage(text,bigint,bigint),public.get_restaurant_billing_dashboard(),public.get_restaurant_team(),public.manage_restaurant_team_member(uuid,text,public.restaurant_member_role,jsonb),public.accept_restaurant_team_invite(text),public.get_platform_subscription_analytics(),public.get_platform_subscription_management(),public.admin_extend_subscription_trial(uuid,integer,text),public.admin_comp_restaurant_subscription(uuid,timestamptz,text),public.admin_create_billing_credit(uuid,integer,text) from public,anon,authenticated;
grant execute on function public.get_restaurant_subscription_usage(),public.assert_restaurant_plan_limit(text,integer),public.record_restaurant_subscription_usage(text,bigint,bigint),public.get_restaurant_billing_dashboard(),public.get_restaurant_team(),public.manage_restaurant_team_member(uuid,text,public.restaurant_member_role,jsonb),public.accept_restaurant_team_invite(text) to authenticated;
grant execute on function public.get_platform_subscription_analytics(),public.get_platform_subscription_management(),public.admin_extend_subscription_trial(uuid,integer,text),public.admin_comp_restaurant_subscription(uuid,timestamptz,text),public.admin_create_billing_credit(uuid,integer,text) to authenticated;

